// ClickUp on a personal API token: every operation of ClickUp's v2 API. actions.json is generated by
// `bun scripts/openapi-actions.ts clickup`; everything a Workspace reports starts automations by webhook (triggers.ts).
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const api: Api = {
  name: "ClickUp",
  base: "https://api.clickup.com/api",
  tokenHelp: "ClickUp → your avatar → Settings → Apps → API Token",
  // ClickUp takes the bare token, no "Bearer"
  auth: (key) => ({ Authorization: key }),
  // a 401 also means this token can't see one Workspace ("Team not authorized"), which isn't a dead login
  deadToken: (status, body) => status === 401 && !/team/i.test(String(body?.err ?? "")),
};

const actions = await specActions(new URL("./actions.json", import.meta.url), api);

export const clickup: OwnApp = {
  app: "clickup",
  name: "ClickUp",
  logo: "/logos/clickup.svg",
  keyField: {
    label: "API token",
    help: "In ClickUp open your avatar → Settings → Apps → under API Token press Generate, then Copy. Emplio can then do whatever your ClickUp account can.",
    placeholder: "pk_...",
  },
  async check(key) {
    const { user } = (await call(api, key, { method: "GET", path: "/v2/user", query: [], headers: [] }, {})) as { user: { id: number; username?: string; email?: string } };
    return user.username || user.email || String(user.id);
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(api, key, connection, event, config),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery) => receive(delivery),
    wanted,
  },
  actions: {
    ...actions,
    // Composio's other names for the same calls, so saved automations carry over
    authorization_get_work_space_list: actions.get_authorized_teams_workspaces!,
    attachments_upload_file_to_task_as_attachment: actions.create_task_attachment!,
  },
};
